"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[5485],{77573:e=>{e.exports=JSON.parse('{"functions":[{"name":"freeSlots","desc":"Seats nobody holds: capacity less the last reported count, less every live\\nreservation. Prune first, or seats already given up still count against it.","params":[{"name":"listing","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"number\\n"}],"function_type":"static","source":{"line":60,"path":"src/internal/Listings.luau"}},{"name":"prune","desc":"Drops reservations that have expired or whose players have arrived. Mutates\\n`listing` and reports whether anything went.","params":[{"name":"listing","desc":"","lua_type":"any"},{"name":"now","desc":"","lua_type":"number"},{"name":"present","desc":"A set of userIds the host currently holds, or `nil` to only age reservations out.","lua_type":"{ [number]: boolean }?"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":87,"path":"src/internal/Listings.luau"}},{"name":"isJoinable","desc":"Whether a ticket of `size` may join. A closed or lapsed listing is refused\\neven while its record survives, since the record outlives the host by design.","params":[{"name":"listing","desc":"","lua_type":"any"},{"name":"size","desc":"","lua_type":"number"},{"name":"now","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":107,"path":"src/internal/Listings.luau"}},{"name":"viewFor","desc":"The reduced copy held in the lane index. Kept small because it is read far\\nmore often than the listing itself.","params":[{"name":"listing","desc":"","lua_type":"any"},{"name":"free","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"ListingView\\n"}],"function_type":"static","source":{"line":117,"path":"src/internal/Listings.luau"}},{"name":"index","desc":"Writes the listing\'s index entry, or removes it once there is nothing left to\\njoin. Removing rather than writing a zero is what keeps a range read full of\\nmatches a searcher can actually use.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"qp","desc":"","lua_type":"any"},{"name":"map","desc":"","lua_type":"string"},{"name":"listing","desc":"","lua_type":"any"},{"name":"free","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean\\n"}],"function_type":"static","source":{"line":138,"path":"src/internal/Listings.luau"}},{"name":"read","desc":"Reads the joinable listings in one lane, oldest generation included.\\n\\nThe lane\'s own map is read first so its entries are the leading run of the\\nresult, which is what lets [LaneScaler] judge this lane\'s depth from them\\nalone. Maps from a generation still draining follow, so a resize never hides a\\nlisting that has not migrated yet.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"descriptor","desc":"","lua_type":"any"},{"name":"count","desc":"","lua_type":"number"}],"returns":[{"desc":"Fullest first.","lua_type":"{ ListingView }"},{"desc":"How many came from the lane\'s own map.","lua_type":"number"}],"function_type":"static","source":{"line":159,"path":"src/internal/Listings.luau"}},{"name":"publish","desc":"Writes a new listing record.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"keys","desc":"","lua_type":"any"},{"name":"qp","desc":"","lua_type":"any"},{"name":"listing","desc":"","lua_type":"any"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":200,"path":"src/internal/Listings.luau"}},{"name":"get","desc":"Reads one listing record.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"keys","desc":"","lua_type":"any"},{"name":"listingId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":209,"path":"src/internal/Listings.luau"}},{"name":"claim","desc":"Takes `reservation.size` seats, or nothing at all.\\n\\nThe whole contention story lives in this transform. See the note on this\\nclass for why one compare-and-set is sufficient.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"keys","desc":"","lua_type":"any"},{"name":"qp","desc":"","lua_type":"any"},{"name":"listingId","desc":"","lua_type":"string"},{"name":"reservation","desc":"","lua_type":"any"},{"name":"now","desc":"","lua_type":"number\\n"}],"returns":[{"desc":"True when the seats are ours.","lua_type":"boolean"},{"desc":"The listing as it stands after the write, for refreshing the index.","lua_type":"any"}],"function_type":"static","source":{"line":223,"path":"src/internal/Listings.luau"}},{"name":"release","desc":"Gives a reservation\'s seats back, for a teleport that failed or a ticket that\\nturned out to be spoken for.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"keys","desc":"","lua_type":"any"},{"name":"qp","desc":"","lua_type":"any"},{"name":"listingId","desc":"","lua_type":"string"},{"name":"reservationId","desc":"","lua_type":"string"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":265,"path":"src/internal/Listings.luau"}},{"name":"heartbeat","desc":"Refreshes a listing: its player count, its lease on life, and whichever\\nreservations have now been fulfilled.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"keys","desc":"","lua_type":"any"},{"name":"qp","desc":"","lua_type":"any"},{"name":"listingId","desc":"","lua_type":"string"},{"name":"update","desc":"`players`, `present`, `open`, and the lane stamp when migrating.","lua_type":"any"},{"name":"now","desc":"","lua_type":"number"}],"returns":[{"desc":"","lua_type":"boolean"},{"desc":"","lua_type":"any"}],"function_type":"static","source":{"line":305,"path":"src/internal/Listings.luau"}},{"name":"remove","desc":"Removes a listing and its index entry outright, for a host shutting down\\ncleanly. A host that dies instead is evicted by `listingExpiration`.","params":[{"name":"store","desc":"","lua_type":"any"},{"name":"keys","desc":"","lua_type":"any"},{"name":"map","desc":"","lua_type":"string"},{"name":"listingId","desc":"","lua_type":"string"}],"returns":[],"function_type":"static","source":{"line":342,"path":"src/internal/Listings.luau"}}],"properties":[],"types":[],"name":"Listings","desc":"Store layout and atomic operations for the Quick Play listing index.\\n\\nThe shape mirrors the ticket index exactly: a hash map holding the record,\\nand a lane sorted map holding a small denormalized copy for discovery.\\nEverything that changes occupancy goes through the hash map, because that is\\nthe only structure the [Store] contract can compare-and-set.\\n\\n### The sort key is free seats\\n\\nEntries are sorted by seats free, ascending, so a range read returns the\\n*fullest joinable* match first, which is what backfill wants: a 7/8 game is\\ncompleted before a 2/8 one is grown. A listing with no seats left is removed\\nfrom the index entirely rather than left in it with a zero, so a range read is\\nnever spent on matches nobody can join.\\n\\n### Why claiming needs no lock\\n\\nFifty lobby servers can see the same 7/8 match at once, and exactly one of\\nthem may take the last seat. `claim` is a single compare-and-set: the store\\nre-runs the loser\'s transform against the winner\'s write, the seat is gone the\\nsecond time around, and the loser moves on to its next candidate. There is no\\nlease and no coordination, because the store is already a serialization point.\\n\\n### Reservations\\n\\nA host reports its player count on a heartbeat, so between beats the count is\\nstale by up to `heartbeatInterval`. A claim writes a *reservation* holding the\\nseats until the players actually arrive, which is what stops two lobbies from\\nboth filling the same slot inside one heartbeat window.\\n\\nA reservation retires in one of two ways, and both matter:\\n\\n- The host\'s next heartbeat reports every one of its userIds as present. They\\n  arrived, so they are already inside `players` and counting them again would\\n  under-fill the match for the rest of the reservation window.\\n- It expires. That is the backstop for a player who took a seat and never\\n  arrived, because their teleport failed or their server died.","private":true,"source":{"line":45,"path":"src/internal/Listings.luau"}}')}}]);